// Checklist content: steps, torque specs and manual paths from the 2007 FJ Cruiser
// factory manuals (RM0240U repair, BM0240U collision). Loaded before app.js.
// ---------- manual paths ----------
const RM = (...p) => "RM0240U@2007 › " + p.join(" › ");
const BM = (...p) => "BM0240U@2007 › " + p.join(" › ");
const S = (f, nm, imp, note, v) => ({f, nm, imp, note: note || "", v});
const TOYTEC = ["ToyTec photos","https://toyteclifts.com/pub/media/mageworx/downloads/attachment/file/0/5/05b1-k_1.pdf"];
const PARTS = ["OEM parts diagrams","https://www.toyotapartsdeal.com/parts-list/2007-toyota-fj_cruiser/body/frame.html"];

// step: {t, d, list, tools, warn, specs, man, refs, v}
const PHASES = [
 {id:"p0", name:"Prep and parts", blurb:"Before any bolt comes out. Measure the new frame now, while it's bare.", steps:[
  {t:"Put the key manual pages where you can see them", d:"Tablet or printouts of the pages you'll use most:", list:["Frame dimension drawings (3 pages)","Cab mount torque (BP-35)","Engine assembly removal and installation","Brake bleeding","VSC zero-point calibration","Front wheel alignment"], tools:["Tablet or printer"], man:[BM("Vehicle Exterior","Body Dimension Drawings"),BM("Vehicle Exterior","Body Panel Replacement","Body Lower Back Panel (Cut)"),RM("Engine-Hybrid System","1GR-FE ENGINE MECHANICAL","ENGINE ASSEMBLY"),RM("Brake","BRAKE","BRAKE FLUID","BLEEDING"),RM("Brake","BRAKE CONTROL","VEHICLE STABILITY CONTROL SYSTEM","CALIBRATION"),RM("Suspension","SUSPENSION","FRONT WHEEL ALIGNMENT","ADJUSTMENT")]},
  {t:"Measure the new frame against the drawing", d:"Level the new frame on stands. Check the heights and log the key diagonals in <a href=\"#frame\">Frame check</a>. Measure the same points on the old frame too, before it's stripped.", tools:["Tracking gauge or tape","Plumb bob or laser","Level","Stands"], man:[BM("Vehicle Exterior","Body Dimension Drawings","General Information"),BM("Vehicle Exterior","Body Dimension Drawings","Frame Dimension-Upper Face (Two-Dimensional Distance)"),BM("Vehicle Exterior","Body Dimension Drawings","Frame Dimension-Upper Face (Three-Dimensional Distance)"),BM("Vehicle Exterior","Body Dimension Drawings","Frame Dimension-Lower Face (Three-Dimensional Distance)")]},
  {t:"Compare every bracket, old frame to new", d:"Check that each attachment point exists and matches:", list:["4 body mount holes per rail (A ø26, C/F/G ø43)","Engine mount frame brackets","No.3 crossmember mounts","Front suspension member brackets","Lower and upper arm pockets","Front diff mounts","Rack mounts","Rear link and lateral rod holes","Shock holes","Stabilizer bracket nuts (M10)","Bumper reinforcement nuts (M10)","Transport hook nuts (M12)","Brake, fuel and harness clip holes"], tools:["Camera","Tape measure"], man:[BM("Vehicle Exterior","Body Dimension Drawings","Frame Dimension-Lower Face (Three-Dimensional Distance)")], refs:[PARTS]},
  {t:"Sort out the VIN", d:"Photograph the VIN stamp on the old frame (front right) and the door-jamb label. Ask your DMV what a replacement frame without a stamp needs before the old one is scrapped.", tools:["Wire brush","Camera"]},
  {t:"Order the single-use parts", d:"These are the parts the manual says to replace:", list:["8 cab mount lock nuts, and cushions if yours are cracked","2 front upper ball joint nuts and clips","2 lower ball joint nuts and cotter pins","Tie rod end and hub nut cotter pins","2 rear shock upper nuts","2 rear stabilizer link-to-frame nuts","All brake hose clips","2 rear caliper union gaskets","Exhaust gaskets and manifold nuts","4 fuel tank cushions","A/C O-rings","A/T control cable clip (A/T)","Brake tubes if yours are rusty"], tools:["OEM parts diagrams"], refs:[PARTS]},
  {t:"Soak every fastener", d:"Wire-brush and soak once a day for 3–5 days: cab mount bolts and nuts, exhaust flanges, link and arm bolts, the front diff mounts, the parking brake cable bolts along the frame.", tools:["Penetrating oil","Wire brush"]},
  {t:"Chase threads and rustproof the new frame", d:"Run a chaser through every weld nut. Blow the frame out and fog the inside of the rails with cavity wax. Toyota specifies PASTAR UWE or PASTAR UC undercoat for chassis and underbody. Degrease and mask first.", tools:["Thread chasers","Compressed air","Cavity wax + wand","Undercoat"], warn:"The manual says not to coat hot parts (exhaust) or moving parts (driveshafts). Keep it off body mount pads, ground points and threads.", man:[BM("Vehicle Exterior","Protective Coatings","Body Panel Undercoating Areas")]},
  {t:"Set up the organization station", d:"Bins, bags, tape, bolt boards, the new-parts bin and plug kit. See <a href=\"#organize\">Keeping it organized</a>.", tools:["Bins","Zip bags","Tape","Paint pens"]},
  {t:"Baseline photos, codes and ride height", d:"Take a walkaround video and underbody photos section by section, and upload the key ones here. Scan and save existing DTCs. Write down whether you have the A/T or M/T, rear diff lock, and A.D.D. front diff. Measure ride height at all four corners for the alignment later.", tools:["OBD2 scanner","Phone","Tape measure"], man:[RM("Suspension","SUSPENSION","FRONT WHEEL ALIGNMENT","ADJUSTMENT")]},
 ]},
 {id:"p1", name:"Front end and engine bay", blurb:"The engine, transmission, rack and axles stay on the frame. The radiator, condenser, brake booster, ECM and airbag sensors are on the body. Everything that runs between the two gets disconnected here.", steps:[
  {t:"Relieve fuel pressure", d:"The fuel pump is controlled by the circuit opening relay in the engine room relay block:", list:["Disconnect the battery negative.","Remove the relay block upper cover and pull the circuit opening relay.","Reconnect the negative, start the engine and let it stall.","Turn the key to ON, crank again and confirm it won't run.","Remove the fuel cap, then reinstall the relay."], tools:["Relay puller","Fire extinguisher"], warn:"Codes P0171/P0174 may set; clear them later. Some pressure remains, so wrap joints with a rag when you open them.", specs:[S("Battery negative terminal","3.9","35 in·lbf")], man:[RM("Engine-Hybrid System","1GR-FE FUEL","FUEL SYSTEM","PRECAUTION")]},
  {t:"Center the steering, tie it, matchmark the shafts", d:"Set the wheels straight ahead. Tie the steering wheel with the seat belt so it can't turn; this protects the spiral cable (airbag clock spring). Matchmark the sliding yoke, the No.2 intermediate shaft and the intermediate shaft, and the No.2 shaft to the gear.", tools:["Paint pen"], warn:"Don't turn the steering wheel once the shaft is apart.", man:[RM("Steering","STEERING COLUMN","STEERING COLUMN ASSEMBLY","REMOVAL")]},
  {t:"Disconnect the battery and wait 90 seconds", d:"Ignition and headlight switch off. Loosen the terminal nut fully without twisting the cable. Wait at least 90 seconds before any airbag-related work; the SRS has a backup power source. Don't use a memory saver. Clock, radio and DTC memory will be erased.", tools:["10 mm wrench"], man:[RM("General","INTRODUCTION","REPAIR INSTRUCTION","PRECAUTION")]},
  {t:"Release brake booster pressure", d:"The FJ has a hydraulic brake booster with an accumulator, not a vacuum booster. With the ignition OFF, press the brake pedal more than 20 times. Don't turn the ignition ON again until the brake work is finished.", tools:["Your foot"], warn:"The brake actuator No.1 tube carries high pressure. Never bend or deform it.", man:[RM("Brake","BRAKE","HYDRAULIC BRAKE BOOSTER","REMOVAL")]},
  {t:"Recover the A/C refrigerant", d:"The charge is R-134a, 570–630 g (20.1–22.2 oz). Have it recovered with a recovery machine, by an A/C shop if you aren't EPA 609 certified.", tools:["Recovery machine or A/C shop"], man:[RM("Vehicle Interior","AIR CONDITIONING","REFRIGERANT","REPLACEMENT")]},
  {t:"Drain the coolant", d:"Remove the service hole cover in the engine under cover and put a hose on the radiator drain. Loosen the 3 drain plugs (radiator and engine), remove the radiator cap and drain the reservoir. Capacity is 9.8 L (A/T) or 9.4 L (M/T).", tools:["Drain pan","Hose"], specs:[S("Engine drain plugs","13","9 ft·lbf"),S("No.1 engine under cover","29","21 ft·lbf")], man:[RM("Engine-Hybrid System","1GR-FE COOLING","COOLANT","REPLACEMENT")]},
  {t:"Remove the hood", d:"Disconnect the washer hose. Remove the 2 stop rings from each support strut; don't touch the strut rods with gloves on. Outline the hinges, then remove the 4 bolts with a helper.", tools:["Metric sockets","Paint pen","Helper"], specs:[S("Hood hinge x hood","13","10 ft·lbf","The engine section lists 18 N·m (13 ft·lbf). Two values in the manual.")], man:[RM("Vehicle Exterior","ENGINE HOOD - DOOR","HOOD","ADJUSTMENT")]},
  {t:"Remove the front bumper", d:"Needed to reach the front cab mounts. In the manual's order:", list:["Radiator grille (2 clips, 2 screws, 5 clips)","Bumper cover (tape the paint; 5 clips, 8 screws, 4 bolts, 2 claws, 4 clips)","Side supports and fillers","Upper retainer (3 bolts)","Reinforcement (4 nuts)","Extensions (4 nuts each)"], tools:["Trim tools","Metric sockets","Helper"], warn:"The front airbag sensors sit behind the grille (2 bolts each, on the body). The manual says to remove an airbag sensor if it's likely to take a knock. Consider removing both before the lift.", specs:[S("Extension x body, reinforcement x extension","65","48 ft·lbf","Collision-safety bolts; torque to spec"),S("Upper retainer","8.0","71 in·lbf"),S("Cover bolts","8.0","71 in·lbf"),S("Cover and side support screws","3.0","27 in·lbf"),S("Front airbag sensor x body","9.0","80 in·lbf")], man:[RM("Vehicle Exterior","EXTERIOR","FRONT BUMPER","REMOVAL"),RM("Vehicle Interior","SUPPLEMENTAL RESTRAINT SYSTEM","FRONT AIRBAG SENSOR","REMOVAL")], refs:[TOYTEC]},
  {t:"Remove the fan, shroud and radiator", d:"The radiator is on the body; the fan is on the engine.", list:["Loosen the 4 fan pulley nuts and remove the belt.","Remove the 4 nuts and the fan with its fluid coupling.","Remove the reserve tank bolt and the 2 shroud bolts, then lift out the shroud.","Remove the upper radiator support seal (7 clips).","Disconnect both radiator hoses, and the 2 oil cooler hoses on the A/T. Plug them.","Remove the 4 radiator bolts."], tools:["Metric sockets","Hose clamp pliers","Line plugs"], specs:[S("Radiator (4 bolts)","21","16 ft·lbf","The spec table misprints this line"),S("Fan pulley nuts","21","16 ft·lbf"),S("Fan x fluid coupling","9.0","80 in·lbf"),S("Fan shroud (2 bolts)","5.0","44 in·lbf"),S("Reserve tank bolt","5.0","44 in·lbf")], man:[RM("Engine-Hybrid System","1GR-FE COOLING","RADIATOR","REMOVAL"),RM("Engine-Hybrid System","1GR-FE COOLING","FAN","REMOVAL")], refs:[TOYTEC]},
  {t:"Disconnect the A/C hoses at the compressor", d:"The compressor stays on the engine; the condenser and evaporator are on the body. Disconnect the suction and discharge hoses at the compressor and seal the openings with vinyl tape. Throw away the O-rings.", tools:["Metric sockets","Vinyl tape","Yellow tape flags"], specs:[S("Suction and discharge hose nuts at compressor","9.8","87 in·lbf","New O-rings oiled with ND-OIL8"),S("Suction hose bracket (timing cover)","7.8","69 in·lbf")], man:[RM("Vehicle Interior","AIR CONDITIONING","COMPRESSOR AND MAGNETIC CLUTCH","REMOVAL")]},
  {t:"Disconnect the heater hoses", d:"Spring clips at the heater unit; slide them with pliers. Note the clip angle and the hose paint marks for reassembly. Cap both ends.", tools:["Hose clamp pliers","Caps"], man:[RM("Vehicle Interior","AIR CONDITIONING","AIR CONDITIONING UNIT","REMOVAL")]},
  {t:"Free the power steering cooler pipe from the body", d:"The collision manual's engine-compartment drawing lists a power steering cooler pipe bracket nut (M6) on the body. Unbolt that bracket so the pipe stays with the chassis. Look for any other PS line clips on the body too.", tools:["10 mm socket"], man:[BM("Vehicle Exterior","Body Dimension Drawings","Body Dimension Drawings-Engine Compartment")]},
  {t:"Remove the airbox and intake tube", d:"Remove the intake tube between the airbox (body) and the throttle body (engine), plus the V-bank cover.", tools:["Screwdriver","10 mm socket"]},
  {t:"Move the washer bottle, filler and dipstick tube", d:"Unbolt and move them aside to reach the front passenger cab mount.", tools:["10 mm socket"], refs:[TOYTEC]},
  {t:"Disconnect the engine harness and pull it into the engine bay", d:"The ECM is <b>inside the cab behind the glove box</b>. The manual's engine removal pulls the harness out through the firewall:", list:["Remove the glove box. On an A/T 4WD, also remove the 4WD control ECU No.2.","Unplug the 3 ECM connectors, the 2 A/C unit connectors, the body ground, and on an A/T 4WD the 4WD ECU and front diff connectors.","Feed the engine wire through the firewall into the engine room.","No.2 engine wire: unplug at the engine room relay block (connector and nut), plus the body ground and the frame ground."], tools:["Trim tools","10/12 mm sockets","Blue tape flags","Zip bags"], warn:"Photograph each connector before unplugging it. Press the release tab and wiggle; old tabs are brittle.", specs:[S("Frame ground","19","14 ft·lbf"),S("Body ground","8.4","74 in·lbf"),S("Relay block wire nut","10","7.4 ft·lbf"),S("ECM nuts (if removed)","8.0","71 in·lbf")], man:[RM("Engine-Hybrid System","1GR-FE ENGINE MECHANICAL","ENGINE ASSEMBLY","REMOVAL"),RM("Engine-Hybrid System","1GR-FE ENGINE CONTROL SYSTEM","ECM","REMOVAL"),"EM0240U › routing"]},
  {t:"Separate the steering shaft", d:"Remove yoke bolts A and B, slide the sliding yoke up off the No.2 intermediate shaft, then pull it down off the intermediate shaft. Check your matchmarks.", tools:["Metric sockets","Paint pen"], specs:[S("Yoke / intermediate shaft bolts A, B, C","36","27 ft·lbf")], man:[RM("Steering","STEERING COLUMN","STEERING COLUMN ASSEMBLY","REMOVAL")], refs:[TOYTEC]},
  {t:"Disconnect the clutch line", v:"mt", d:"Separate the clutch tube at the flexible hose, using the 10 mm flare wrench, where the line passes from the body to the transmission. Plug both ends; don't let the reservoir run dry.", tools:["10 mm flare-nut wrench","Plugs"], specs:[S("Release cylinder flexible hose tube","15","11 ft·lbf"),S("Accumulator hose tube flare nut","15","11 ft·lbf"),S("Clutch line bracket","12","8.7 ft·lbf")], man:[RM("Drivetrain","CLUTCH","CLUTCH RELEASE CYLINDER","REMOVAL")]},
  {t:"Breathers and vacuum lines", d:"Unhook the diff, transfer and A.D.D. breather and vacuum lines that run up to the body or engine bay. The front diff breather bracket is 1 bolt. Label each one.", tools:["Pliers","Green tape"], specs:[S("Front diff breather bracket","13","10 ft·lbf")]},
  {t:"Unclip the front fender splash shields", d:"Pull the splash shield clips (5–6 per side; the manual's pages don't agree on the count) where they meet the frame side.", tools:["Clip pliers"]},
 ]},
 {id:"p2", name:"Cab, underbody and rear", blurb:"Reach the cab mounts from inside, then deal with everything underneath that connects the body to the chassis.", steps:[
  {t:"Open up the front floor", d:"Remove:", list:["Front and rear door scuff plates (14 and 6 claws)","Footrest (4 claws, 2 clips)","Cowl side trim boards (1 clip, 2 claws each)","Lower instrument panel finish panel LH"], tools:["Trim tools"], after:"Pull the carpet back to reach the front cab mounts.", man:[RM("Vehicle Interior","INTERIOR","FRONT FLOOR FOOTREST","REMOVAL"),RM("Vehicle Interior","INSTRUMENT PANEL","INSTRUMENT PANEL ASSEMBLY","REMOVAL")], refs:[TOYTEC]},
  {t:"Open up the rear floor", d:"Remove:", list:["Rear seatbacks and cushions (2 bolts each)","Rear floor board and mat support plate (5 screws)","Luggage strikers and rear floor mat","Deck trim cover (8 claws)","Deck trim side panels (RH 4 screws, LH 3)"], tools:["Trim tools","Metric sockets"], after:"This exposes the access holes for the mounts ahead of the rear tires and at the rear.", specs:[S("Rear seat cushion / seatback bolts","37","27 ft·lbf"),S("Rear seat outer belt anchors","42","31 ft·lbf")], man:[RM("Vehicle Interior","INTERIOR","ROOF HEADLINING","REMOVAL"),RM("Vehicle Interior","SEAT","REAR SEAT ASSEMBLY (for RH Side)","REMOVAL")], refs:[TOYTEC]},
  {t:"Disconnect the fuel pump connector", d:"Under the rear seat at the center floor LH: remove the service hole cover (3 screws) and unplug the pump connector.", tools:["Phillips"], man:[RM("Engine-Hybrid System","1GR-FE FUEL","FUEL TANK","REMOVAL")]},
  {t:"Remove the automatic shifter linkages", v:"at", d:"<b>Transfer lever:</b> remove the A/T and transfer knobs and the boot (4 screws). Remove the snap ring and pull the transfer high/low lever out of its retainer. <b>A/T cable:</b> at the transmission, remove the nut and clip to free the cable, and 2 bolts for the bracket. Photograph the adjustment first.", tools:["Snap ring pliers","Pliers","Metric sockets"], specs:[S("Control cable nut at transmission","14","10 ft·lbf","New clip"),S("Control cable bracket","14","10 ft·lbf")], man:[RM("Drivetrain","A750F AUTOMATIC TRANSMISSION","TRANSMISSION CONTROL CABLE","REMOVAL")]},
  {t:"Remove the manual shift levers", v:"mt", d:"Remove the transfer and M/T knobs and the boot (4 screws, 2 clips). Transfer lever: snap ring off, pull it from the retainer. M/T lever: lift the cap boot, cover the cap with a rag, press down, turn counterclockwise and pull it out.", tools:["Snap ring pliers","Rag"], man:[RM("Drivetrain","RA61F MANUAL TRANSMISSION","MANUAL TRANSMISSION ASSEMBLY","REMOVAL")]},
  {t:"Unhook the parking brake cables inside the cab", d:"There's no equalizer under the truck. The rear cables (No.2 and No.3) hook directly to the pull rod at the lever under the console. Loosen the adjusting nut, unhook the cable ends, squeeze the spring cap claws and push the cables down through the floor. They stay with the chassis.", tools:["Metric sockets","Pliers"], man:[RM("Brake","PARKING BRAKE","PARKING BRAKE CABLE","REMOVAL")]},
  {t:"Split the brake lines away from the booster", d:"Follow the 4 tubes from the hydraulic booster on the cowl down to where they leave the body. Separate them at the first union past the body and plug each end immediately. Tag all 4 tubes.", tools:["10 mm flare-nut wrench","Line plugs","Red tape","Rags"], warn:"Don't open the lines at the booster, and don't let the reservoir run dry. If either happens, the manual requires a master cylinder solenoid bleed with a Techstream scan tool.", specs:[S("Brake line flare (union) nuts","15","11 ft·lbf","14 N·m (10 ft·lbf) using SST 09023-00101 on a 300 mm wrench")], man:[RM("Brake","BRAKE","HYDRAULIC BRAKE BOOSTER","REMOVAL"),RM("Brake","BRAKE","BRAKE FLUID","BLEEDING")]},
  {t:"Drop the fuel tank", d:"The spec table lists the tank bands and the charcoal canister as mounted to the body. Dropping the tank now avoids surprises either way. It's also needed to swap the lines.", list:["Loosen the filler hose clamp and disconnect the breather tube quick connector.","Remove the No.1 protector (4 nuts, bracket nut).","Disconnect the main and return tube quick connectors and the vent hose.","Support the tank on a jack and remove the 2 bands."], tools:["Transmission jack","Metric sockets","Plugs","Fire extinguisher"], warn:"Quick connectors: pinch the retainer and pull by hand, never with tools. Clean them first and bag the ends. Don't bend or twist the nylon tubes.", specs:[S("Fuel tank band","40","30 ft·lbf"),S("No.1 protector x band","20","15 ft·lbf"),S("Protector bracket","5.5","49 in·lbf"),S("No.3 protector x tank","5.0","44 in·lbf")], man:[RM("Engine-Hybrid System","1GR-FE FUEL","FUEL TANK","REMOVAL")]},
  {t:"Disconnect the EVAP canister lines", d:"The canister is near the tank, bolted to the body (3 bolts). Disconnect the tank vent/breather quick connector, the No.2 canister outlet hose, the EVAP hose and the leak detection pump connector. Unhook the 2 clamps on the breather tube.", tools:["Pliers","Plugs"], specs:[S("Charcoal canister x body","20","15 ft·lbf")], man:[RM("Engine-Hybrid System","1GR-FE EMISSION CONTROL","CANISTER","REMOVAL")]},
  {t:"Unplug the chassis harness connectors", d:"Anywhere a body harness meets a chassis harness: ABS sensor leads, rear diff lock actuator (plus its breather hose), A.D.D. actuator (connector and vacuum hose), trailer wiring, and frame grounds. Flag both halves of each connector.", tools:["Trim tools","Picks","Blue tape"], man:["EM0240U › routing",RM("Drivetrain","DIFFERENTIAL","DIFFERENTIAL VACUUM ACTUATOR","REPLACEMENT")]},
  {t:"Break loose the 8 cab mount bolts", d:"There are 4 mounts per side: the manual names them No.1, No.2, No.4 and the rear end cab mount. Break them all loose and then run the nuts back on a couple of turns until lift day. The lock nuts are single-use, so throw them out when they come off.", tools:["1/2″ breaker bar","Impact","Deep sockets","Induction heater or torch","Cutoff wheel"], warn:"If a bolt spins, hold it through the access hole inside the cab. If it still won't hold, cut it off and fix the body-side mount before reassembly.", specs:[S("Cab mounts No.1, No.2, No.4, rear end","45","33 ft·lbf","Tighten vertically; new lock nuts")], man:[BM("Vehicle Exterior","Body Panel Replacement","Body Lower Back Panel (Cut)")], refs:[TOYTEC]},
  {t:"Know what stays on the body", d:"Leave these on the body; they lift off with it:", list:["Rear bumper","Side steps (6 bolts)","Mud guards","Charcoal canister","Radiator and condenser","Brake booster","ECM","Front airbag sensors","Yaw rate sensor (under the console)"], after:"Everything else in the drivetrain and suspension stays on the frame.", tools:["Flashlight"], man:[RM("General","SERVICE SPECIFICATIONS","EXTERIOR","TORQUE SPECIFICATIONS")]},
 ]},
 {id:"p3", name:"Lift the body", blurb:"The manual's lift rules: rubber pads, lock the arms, lift slightly and shake the vehicle to check it's stable. Removing heavy parts shifts the center of gravity.", steps:[
  {t:"Final walkaround", d:"Go through phases 1 and 2 again with a flashlight and look for anything still running between the body and the chassis. Check the shifter area, parking brake cables, steering yoke, harness at the firewall, brake lines, PS cooler pipe, breathers and filler neck.", tools:["Flashlight","Mirror"]},
  {t:"Have somewhere to set the body down", d:"A body dolly (square tube or 4×4 frame with casters under the mount areas) or 4 tall stands. Setting the body down frees the lift for the chassis work.", tools:["Dolly or tall stands"]},
  {t:"Set the lift arms on the body", d:"The factory lift points are on the frame, so choose body pickup points next to the cab mount brackets and floor structure. Use rubber pads, wood blocks and tall adapters. Keep the doors on and closed. Center the body's weight between the arms and lock the arms.", tools:["2×6 blocks","Tall adapters"], warn:"Don't lift on the rocker pinch welds alone. With the engine staying on the frame, the empty body is light in front, so find its balance before you go high.", man:[RM("General","INTRODUCTION","REPAIR INSTRUCTION","VEHICLE LIFT AND SUPPORT LOCATIONS"),BM("General","Introduction","Notice About Vehicle Condition When Jacking Up Vehicle")]},
  {t:"Remove the nuts, lift 2–3 inches, shake-test", d:"Lift slightly, then gently rock the body to check it's stable, as the manual says. Walk all the way around with two helpers.", tools:["2 helpers"], refs:[TOYTEC]},
  {t:"Raise to clear the engine and lock", d:"Keep going until the intake and the top of the engine clear the radiator support and firewall.", tools:["2 helpers"]},
  {t:"Roll the chassis out", d:"Wheels straight, then push it clear of the lift.", tools:["2 helpers"], warn:"Nobody goes under the raised body."},
  {t:"Set the body on the dolly or stands", d:"Lower the body onto its supports and check it's stable before walking away.", tools:["Dolly or stands"]},
 ]},
 {id:"p4", name:"Strip the old chassis", blurb:"The old frame is your template for line and clip routing. Document it before you take anything off.", steps:[
  {t:"Document routing on the old frame", d:"Put a numbered tape flag at every brake, fuel and harness clip. Photograph each one and measure it from a frame reference hole. Take the frame measurements now too (Frame check).", tools:["Tape flags","Tape measure","Camera"]},
  {t:"Remove the propeller shafts", d:"Matchmark each flange to the diff and the transfer, then remove the 4 bolts or nuts at each end.", tools:["Paint pen","Metric sockets"], specs:[S("All propeller shaft flange joints","88","65 ft·lbf")], man:[RM("Drivetrain","PROPELLER SHAFT","REAR PROPELLER SHAFT ASSEMBLY","REMOVAL"),RM("Drivetrain","PROPELLER SHAFT","FRONT PROPELLER SHAFT ASSEMBLY (for 4WD)","REMOVAL")]},
  {t:"Remove the exhaust", d:"Unplug the heated oxygen sensors first, then remove the tail pipe, center pipe (with springs), No.2 front pipe and front pipe. The gaskets and manifold nuts are single-use.", tools:["O2 sensor socket","Penetrating oil","Torch"], specs:[S("Front pipe x manifold","54","40 ft·lbf","New nuts and gaskets"),S("No.2 front pipe nut","54","40 ft·lbf"),S("No.2 front pipe bolt","48","35 ft·lbf"),S("Center pipe bolts (with springs)","43","32 ft·lbf","Spring free length at least 40.5 mm"),S("Tail pipe","48","35 ft·lbf"),S("Stopper bracket (4WD)","19","14 ft·lbf"),S("Heated O2 sensor","44","33 ft·lbf","The exhaust table says 43")], man:[RM("Engine-Hybrid System","1GR-FE EXHAUST","EXHAUST PIPE","REMOVAL")]},
  {t:"Remove the engine, transmission and transfer case", d:"Moving them as one unit:", list:["Disconnect and cap the power steering pressure feed tube at the gear.","Hang the engine from the hangers with a leveler.","Support the transmission on a jack.","Remove the front suspension member brackets (4 bolts each side).","Remove the No.3 frame crossmember.","Remove the 4 bolts and 4 nuts holding the engine mount insulators to the frame brackets.","Lift and roll it out."], tools:["Engine hoist","Load leveler","Transmission jack","Line caps","Helper"], specs:[S("Engine mount insulators x frame brackets (4 bolts, 4 nuts)","38","28 ft·lbf"),S("No.3 frame crossmember (4 bolts + 4 nuts)","72","53 ft·lbf"),S("No.3 crossmember x mount insulator (4)","19","14 ft·lbf"),S("Rear No.1 mount insulator x transmission (4)","65","48 ft·lbf"),S("Front suspension member brackets","33","24 ft·lbf"),S("Engine hanger bolts","33","24 ft·lbf")], man:[RM("Engine-Hybrid System","1GR-FE ENGINE MECHANICAL","ENGINE ASSEMBLY","INSTALLATION")]},
  {t:"Remove the front suspension and axles", d:"Matchmark the No.2 camber adjust cam and the toe adjust cam on each lower arm first.", list:["Hang the calipers; don't let them hang on the hoses.","Hub nut cotter pin and lock cap off, then the hub nut.","Separate the tie rod ends (puller) and the lower ball joint attachments (2 bolts).","Pull the drive shafts.","Remove the coilovers (3 upper nuts), stabilizer, and upper and lower arms."], tools:["Tie rod puller","Drive shaft puller","Breaker bar","Bungees","Paint pen"], specs:[S("Front caliper x knuckle","123","91 ft·lbf"),S("Front hub nut (4WD)","235","174 ft·lbf","New cotter pin")], man:[RM("Suspension","SUSPENSION","FRONT LOWER SUSPENSION ARM","REMOVAL"),RM("Drivetrain","DRIVE SHAFT","FRONT DRIVE SHAFT (for 4WD)","REMOVAL")]},
  {t:"Remove the front differential", d:"Drain it. Remove the breather bracket bolt and disconnect the A.D.D. connector and vacuum hose if you have them. Support it on a jack, remove the No.1 mounting nut, then the 2 mounting bolts and 2 nuts, and lower it.", tools:["Transmission jack","Metric sockets"], man:[RM("Drivetrain","DIFFERENTIAL","FRONT DIFFERENTIAL CARRIER ASSEMBLY","REMOVAL")]},
  {t:"Remove the steering gear", d:"Disconnect the return hose (clip only). Remove the 2 bolts and 2 nuts holding the gear to the frame.", tools:["Metric sockets"], warn:"The nuts have a detent. On install, turn only the bolt, never the nut.", man:[RM("Steering","POWER STEERING","POWER STEERING LINK (for 4WD)","REMOVAL")]},
  {t:"Remove the rear axle", d:"Support the housing first.", list:["Separate the brake tubes from the flexible hoses and remove the clips.","Unplug the ABS sensor leads and the diff lock actuator and breather.","Remove the shocks, stabilizer links, lateral rod, and upper and lower arms.","Lower the housing and springs slowly."], tools:["2 floor jacks","10 mm flare-nut wrench","Metric sockets"], warn:"The manual says not to snap the brake line or parking brake cable as the housing comes down.", man:[RM("Suspension","SUSPENSION","REAR COIL SPRING","REMOVAL"),RM("Suspension","SUSPENSION","REAR LOWER CONTROL ARM","REMOVAL")]},
  {t:"Remove the lines, cables and harness from the old frame", d:"Brake tubes and hoses, fuel and EVAP lines. The parking brake cables have 5 bolts along the frame, with the RH heat insulator (2 bolts) off first. Also the frame harness, bumper brackets, tow hooks and heat shields. Bag it all by location.", tools:["Flare-nut wrenches","Metric sockets","Zip bags"], specs:[S("Parking brake cable x frame (5 bolts)","13","9 ft·lbf"),S("Cable heat insulator x frame","13","9 ft·lbf")], man:[RM("Brake","PARKING BRAKE","PARKING BRAKE CABLE","REMOVAL")]},
 ]},
 {id:"p5", name:"Build the new chassis", blurb:"Snug every suspension pivot bolt now. Final torque happens at ride height in phase 7, so the bushings aren't twisted.", steps:[
  {t:"New frame level on stands", d:"Confirm the frame check is logged and nothing is out of range.", tools:["Stands","Level"]},
  {t:"Run the brake, fuel and EVAP lines", d:"Follow your routing photos and use new clips. The manual's checks: lines clear of sharp edges, moving parts and the exhaust, and centered in any grommet.", tools:["Tubing cutter","Bender","Flaring tool","10 mm flare-nut wrench"], specs:[S("Brake flare (union) nuts","15","11 ft·lbf","14 N·m with SST")], man:[RM("General","MAINTENANCE","BRAKE","GENERAL MAINTENANCE")]},
  {t:"Install the parking brake cables", d:"Route them as they came off. The cable ends stay loose at the top until the body is back on.", tools:["Metric sockets"], specs:[S("Cable x frame (5 bolts)","13","9 ft·lbf"),S("Heat insulator x frame","13","9 ft·lbf"),S("Cable x lower arm","13","9 ft·lbf"),S("Cable x parking brake plate","8.0","71 in·lbf")], man:[RM("Brake","PARKING BRAKE","PARKING BRAKE CABLE","INSTALLATION")]},
  {t:"Install the rear axle", d:"Set the coil spring lower ends into the gaps in the spring seats. Snug the arms, lateral rod and lower shock bolts; final torque at ride height.", tools:["2 floor jacks","Metric sockets"], specs:[S("Upper control arms x frame and axle","80","59 ft·lbf","Ride height. Hold the bolt, turn the nut."),S("Lower control arms x frame and axle","130","96 ft·lbf","Ride height. Hold the nut, turn the bolt."),S("Lateral control rod x frame and axle","130","96 ft·lbf","Ride height. Hold the nut, turn the bolt."),S("Rear shock upper x frame","25","18 ft·lbf","New nut; hold the piston rod"),S("Rear shock lower x axle","98","72 ft·lbf","Ride height"),S("Stabilizer bracket cover x axle","30","22 ft·lbf"),S("Stabilizer link x bar","70","52 ft·lbf"),S("Stabilizer link x frame","15","11 ft·lbf","New nut"),S("Rear caliper mounting x axle","100","74 ft·lbf"),S("Rear caliper x mounting","88","65 ft·lbf"),S("Rear flexible hose x caliper union bolt","31","23 ft·lbf","New gasket"),S("Brake tube x flexible hose","15","11 ft·lbf","New clips"),S("Rear speed sensor","8.3","73 in·lbf")], man:[RM("Suspension","SUSPENSION","REAR UPPER CONTROL ARM","INSTALLATION"),RM("Suspension","SUSPENSION","REAR LATERAL CONTROL ROD","INSTALLATION")]},
  {t:"Install the front differential", d:"Bolt the supports to the carrier, then lift it into place.", tools:["Transmission jack","Torque wrench"], specs:[S("No.1 support x carrier","186","137 ft·lbf"),S("No.2 support x carrier","160","118 ft·lbf","One manual page misprints 11 ft·lbf"),S("No.3 support x carrier","108","80 ft·lbf"),S("Front diff mounting bolts and nuts x frame","137","101 ft·lbf"),S("No.1 diff mounting nut","87","64 ft·lbf"),S("A.D.D. actuator bolts","21","15 ft·lbf"),S("Breather bracket","13","10 ft·lbf")], man:[RM("Drivetrain","DIFFERENTIAL","FRONT DIFFERENTIAL CARRIER ASSEMBLY","INSTALLATION")]},
  {t:"Install the steering gear", d:"Turn only the bolt; the nut has a detent. Tie rod ends go on after the knuckles.", tools:["Torque wrench"], specs:[S("Steering gear x frame (2 bolts, 2 nuts)","100","74 ft·lbf","Turn only the bolt"),S("PS tube brackets","28","21 ft·lbf")], man:[RM("Steering","POWER STEERING","POWER STEERING LINK (for 4WD)","INSTALLATION")]},
  {t:"Install the front suspension", d:"Line up the camber and toe cam matchmarks on the lower arms. The coil spring's lower end faces the rear of the vehicle. Fit the stabilizer bushings outboard of the stoppers, protrusion facing in. Snug the lower and upper arm pivots and the coilover lower bolts; final torque at ride height.", tools:["Torque wrench","6 mm hex"], specs:[S("Lower arm x frame","135","100 ft·lbf","Ride height"),S("Upper arm x frame","115","85 ft·lbf","Ride height"),S("Coilover upper (3 nuts)","64","47 ft·lbf"),S("Coilover lower x lower arm","135","100 ft·lbf","Ride height"),S("Upper ball joint x knuckle","110","81 ft·lbf","New nut and clip"),S("Lower ball joint x lower arm","140","103 ft·lbf","New nut and cotter pin"),S("Lower ball joint attachment x knuckle","160","118 ft·lbf"),S("Stabilizer bracket x frame","40","30 ft·lbf"),S("Stabilizer link x bar / x knuckle","70","52 ft·lbf","Hold the stud with a 6 mm hex"),S("Tie rod end x knuckle","91","67 ft·lbf","New cotter pin. The PS spec table says 49; every procedure page says 91."),S("Tie rod lock nut","88","65 ft·lbf")], man:[RM("Suspension","SUSPENSION","FRONT LOWER SUSPENSION ARM","INSTALLATION"),RM("Suspension","SUSPENSION","FRONT SHOCK ABSORBER WITH COIL SPRING","INSTALLATION")]},
  {t:"Install the drive shafts, hubs and front brakes", d:"Coat the inboard splines with ATF and drive the shafts in with a brass bar, snap ring opening facing down. Matchmark the brake discs to the hubs.", tools:["Brass bar","Torque wrench"], specs:[S("Front hub nut (4WD)","235","174 ft·lbf","Lock cap, new cotter pin"),S("Axle hub x knuckle","80","59 ft·lbf"),S("Front caliper x knuckle","123","91 ft·lbf"),S("Front speed sensor","8.3","73 in·lbf"),S("Brake tube bracket","29","21 ft·lbf")], man:[RM("Drivetrain","DRIVE SHAFT","FRONT DRIVE SHAFT (for 4WD)","INSTALLATION")]},
  {t:"Install the engine, transmission and transfer case", d:"Lower them onto the mount insulators with the transmission on a jack, then install the No.3 crossmember and the front suspension member brackets. Reconnect the PS pressure feed tube at the gear.", tools:["Engine hoist","Leveler","Transmission jack","Torque wrench"], specs:[S("Engine mount insulators x frame brackets","38","28 ft·lbf"),S("No.3 frame crossmember","72","53 ft·lbf"),S("No.3 crossmember x mount insulator","19","14 ft·lbf"),S("Rear No.1 mount insulator x transmission","65","48 ft·lbf"),S("Front suspension member brackets","33","24 ft·lbf"),S("PS pressure feed tube at gear","44","33 ft·lbf","42 N·m (31 ft·lbf) with SST 09023-12701")], man:[RM("Engine-Hybrid System","1GR-FE ENGINE MECHANICAL","ENGINE ASSEMBLY","INSTALLATION")]},
  {t:"Install the exhaust and propeller shafts", d:"New gaskets, and new nuts at the manifolds. Line up the propeller shaft matchmarks.", tools:["Torque wrench"], specs:[S("Front pipe x manifold","54","40 ft·lbf","New nuts"),S("Center pipe bolts","43","32 ft·lbf"),S("Tail pipe","48","35 ft·lbf"),S("Propeller shaft flanges","88","65 ft·lbf"),S("Propeller shaft heat insulator","16","12 ft·lbf")], man:[RM("Engine-Hybrid System","1GR-FE EXHAUST","EXHAUST PIPE","INSTALLATION")]},
  {t:"Harness, grounds and wheels", d:"Clip the frame harness where your photos show it. Frame grounds go on clean metal.", tools:["Torque wrench"], specs:[S("Frame ground","19","14 ft·lbf"),S("Wheel nuts, steel wheels","112","82 ft·lbf"),S("Wheel nuts, aluminum wheels","103","76 ft·lbf")]},
  {t:"Clearance check", d:"Make sure nothing on the chassis sits higher than the body mount pads where it would hit the floor. Check the transfer lever tower, the parking brake cable ends and the harness.", tools:["Straightedge","Flashlight"]},
 ]},
 {id:"p6", name:"Body drop and reconnect", blurb:"Phases 1 and 2 in reverse. Use your bag numbers and photos.", steps:[
  {t:"Raise the body and roll the new chassis under", tools:["2-post lift","2 helpers"]},
  {t:"Fit the cab mount cushions", d:"Put the new or reused cushions on the frame brackets in the order your photos show.", tools:["Cushions","Photos"], refs:[PARTS]},
  {t:"Lower the body onto alignment pins", d:"Drop punches or long bolts through the mount holes. As it comes down, watch the steering yoke, the transfer lever tower, the parking brake cables through the floor, the harness at the firewall and the filler neck. The manual says to check that each body mounting hole is in the correct position.", tools:["Drift punches","2 helpers"], man:[BM("Vehicle Exterior","Body Panel Replacement","Body Lower Back Panel (Cut)")]},
  {t:"Torque the cab mounts", d:"Start all 8 by hand with <b>new lock nuts</b>. Tighten each bolt vertically (square to the mount).", tools:["Torque wrench","Deep sockets"], specs:[S("Cab mounts No.1, No.2, No.4, rear end","45","33 ft·lbf","New lock nuts (single-use)")], man:[BM("Vehicle Exterior","Body Panel Replacement","Body Lower Back Panel (Cut)")]},
  {t:"Reconnect the steering shaft", d:"Line up the matchmarks, then untie the steering wheel.", tools:["Torque wrench"], specs:[S("Yoke / intermediate shaft bolts A, B, C","36","27 ft·lbf")], man:[RM("Steering","STEERING COLUMN","STEERING COLUMN ASSEMBLY","INSTALLATION")]},
  {t:"Feed the harness back and plug everything in", d:"Feed the engine wire back through the firewall. Plug in the ECM (3), A/C unit (2) and, on the A/T 4WD, the 4WD ECU and front diff connectors. Reconnect the relay block connector and nut, and every ground. Then the fuel pump connector and the chassis connectors.", tools:["Trim tools","Torque wrench"], specs:[S("Frame ground","19","14 ft·lbf"),S("Body ground","8.4","74 in·lbf"),S("Relay block wire nut","10","7.4 ft·lbf"),S("ECM nuts","8.0","71 in·lbf")], man:[RM("Engine-Hybrid System","1GR-FE ENGINE MECHANICAL","ENGINE ASSEMBLY","INSTALLATION")]},
  {t:"Reconnect the A/T shift cable and transfer lever", v:"at", d:"Cable to the transmission with a new clip. To adjust: push the control shaft fully rearward, turn it back 2 notches to N, and set the shift lever to N. Refit the transfer lever and its snap ring.", tools:["Snap ring pliers","Torque wrench"], specs:[S("Control cable nut","14","10 ft·lbf"),S("Control cable bracket","14","10 ft·lbf"),S("Control cable x body nuts","5.5","49 in·lbf")], man:[RM("Drivetrain","A750F AUTOMATIC TRANSMISSION","FLOOR SHIFT ASSEMBLY","ADJUSTMENT")]},
  {t:"Refit the M/T and transfer levers", v:"mt", d:"Put MP grease on the M/T lever tip, press it in and turn clockwise. Refit the transfer lever and its snap ring.", tools:["MP grease","Snap ring pliers"], man:[RM("Drivetrain","RA61F MANUAL TRANSMISSION","MANUAL TRANSMISSION ASSEMBLY","INSTALLATION")]},
  {t:"Reconnect and adjust the parking brake", d:"Hook the cables back onto the pull rod. Set the lever travel with the adjusting nut: <b>5–7 clicks at 200 N (45 lbf)</b>. Work the lever 3–4 times, check for drag, and check the warning light comes on at the first click.", tools:["Metric sockets"], specs:[S("Parking brake lever x body","13","9 ft·lbf")], man:[RM("Brake","PARKING BRAKE","PARKING BRAKE LEVER","ON-VEHICLE INSPECTION")]},
  {t:"Reconnect brake, clutch, fuel and EVAP lines", d:"Brake unions at the body-to-chassis joints, and the clutch line (M/T). Fuel and EVAP quick connectors: push in until they click, then pull to confirm. Then the filler hose clamp.", tools:["10 mm flare-nut wrench","Torque wrench"], specs:[S("Brake flare (union) nuts","15","11 ft·lbf","14 N·m with SST"),S("Clutch flexible hose tube (M/T)","15","11 ft·lbf",null,"mt")], man:[RM("Engine-Hybrid System","1GR-FE FUEL","FUEL TANK","INSTALLATION")]},
  {t:"Reconnect A/C, heater and radiator", d:"A/C hoses at the compressor with new O-rings, oiled with ND-OIL8. Heater hoses with their spring clips at the marked angle. Then the radiator, A/T cooler hoses, shroud, fan and belt, the upper support seal, and the PS cooler pipe bracket on the body.", tools:["Torque wrench","Hose clamp pliers"], specs:[S("A/C hoses at compressor","9.8","87 in·lbf"),S("Radiator (4 bolts)","21","16 ft·lbf"),S("Fan pulley nuts","21","16 ft·lbf"),S("Fan x fluid coupling","9.0","80 in·lbf"),S("Fan shroud","5.0","44 in·lbf")], man:[RM("Engine-Hybrid System","1GR-FE COOLING","RADIATOR","INSTALLATION"),RM("Vehicle Interior","AIR CONDITIONING","COMPRESSOR AND MAGNETIC CLUTCH","INSTALLATION")]},
  {t:"Refit the front bumper, airbag sensors and hood", d:"Hood gaps: A 4–7 mm, B 1.4–4.4 mm, C 5–8 mm. The hood hinges use centering bolts; swap in standard bolts with washers if you need to adjust.", tools:["Torque wrench","Helper"], specs:[S("Bumper extension / reinforcement","65","48 ft·lbf"),S("Front airbag sensor x body","9.0","80 in·lbf"),S("Hood hinge x hood","13","10 ft·lbf","18 N·m in the engine section"),S("Hood lock","8.0","71 in·lbf")], man:[RM("Vehicle Exterior","EXTERIOR","FRONT BUMPER","INSTALLATION"),RM("Vehicle Exterior","ENGINE HOOD - DOOR","HOOD","ADJUSTMENT")]},
  {t:"Refit the interior", d:"Carpet, trim, seats and belts. Front seats: with the seat fully rearward, tighten the front bolts first. Then slide it fully forward and tighten the rear bolts.", tools:["Trim tools","Torque wrench"], specs:[S("Front seat bolts","37","27 ft·lbf"),S("Rear seat cushion / seatback","37","27 ft·lbf"),S("Seat belt anchors","42","31 ft·lbf"),S("Rear seat lock striker","18","13 ft·lbf")], man:[RM("Vehicle Interior","SEAT","FRONT SEAT ASSEMBLY","INSTALLATION")]},
 ]},
 {id:"p7", name:"Fluids, bleeding, alignment and calibration", blurb:"The order matters: brakes before driving, alignment before VSC calibration.", steps:[
  {t:"Battery on, fuel leak check", d:"Reconnect the battery. Turn the key to ON a few times to prime the fuel system and check every fuel joint before you start the engine. Clear P0171/P0174 from the pressure relief.", tools:["10 mm wrench","Flashlight","Fire extinguisher"], specs:[S("Battery terminal","3.9","35 in·lbf")]},
  {t:"Bleed the brakes", d:"The manual's sequence:", list:["Bleed the booster and accumulator: key ON and wait for the pump to stop, then key OFF and pump the pedal 20+ times. Repeat 5 times. Key ON, check the pump stops in about 8–14 s.","Front lines: with the key ON and the pump stopped, pump and hold the pedal, open the bleeder, close it, release. Repeat until clear.","Rear lines: hold the pedal down and open the bleeder; fluid flows out on its own. Keep the reservoir above MIN.","Level: key OFF, pump 20+ times, fill to MAX. It normally drops about 5 mm at key ON."], tools:["Pressure bleeder","Clear hose","DOT 3"], warn:"If the reservoir ran empty or a line was opened at the booster, you also need the master cylinder solenoid bleed (Techstream Active Test \"SRMF\").", specs:[S("Bleeder plugs","11","8 ft·lbf")], man:[RM("Brake","BRAKE","BRAKE FLUID","BLEEDING")]},
  {t:"Bleed the clutch", v:"mt", d:"Fill the brake reservoir and bleed the clutch at the release cylinder bleeder.", tools:["Clear hose","DOT 3"], specs:[S("Clutch bleeder plug","11","8 ft·lbf")], man:[RM("Drivetrain","CLUTCH","CLUTCH RELEASE CYLINDER","INSTALLATION")]},
  {t:"Fill and bleed the coolant", d:"Fill the radiator to overflow, squeezing the hoses as you go. Cap it and fill the reservoir to FULL. Warm up at 2,000–2,500 rpm with the heater blower on, temp at WARM and A/C off until the fan runs, squeezing the hoses to push air out. Let it cool, top up, and repeat until the level holds.", tools:["Spill-free funnel","Toyota SLLC"], specs:[S("Cooling system leak test pressure","177 kPa","25.7 psi")], man:[RM("Engine-Hybrid System","1GR-FE COOLING","COOLANT","REPLACEMENT")]},
  {t:"Bleed the power steering", d:"Turn lock to lock with the engine off, then again at idle, holding 2–3 s at each lock. Check the reservoir level.", tools:["Helper"], man:[RM("Steering","POWER STEERING","POWER STEERING SYSTEM","ON-VEHICLE INSPECTION")]},
  {t:"Evacuate and recharge the A/C", d:"Pull a vacuum and check it holds, then charge 570–630 g of R-134a. Don't start the engine before charging. Afterward, warm up under 2,000 rpm for at least 2 minutes.", tools:["Vacuum pump and gauges, or A/C shop","R-134a"], man:[RM("Vehicle Interior","AIR CONDITIONING","REFRIGERANT","REPLACEMENT")]},
  {t:"Check the A/T fluid", v:"at", d:"If any fluid was lost, top up and check it at temperature:", list:["Start with the fluid below 30°C.","Enter temperature mode: jumper DLC3 TC (13) to CG (4), start the engine, and move the lever P to L and back.","Then shift to D and toggle N↔D for at least 6 s. The A/T OIL TEMP light shows 2 s, then goes off.","Idle until the light comes on (36–46°C).","Remove the overflow plug; fluid should trickle out."], tools:["DLC3 jumper","ATF WS"], specs:[S("Overflow plug","20","15 ft·lbf"),S("Refill plug","39","29 ft·lbf"),S("Drain plug","28","21 ft·lbf")], man:[RM("Drivetrain","A750F AUTOMATIC TRANSMISSION","AUTOMATIC TRANSMISSION FLUID","ADJUSTMENT")]},
  {t:"Check transfer and diff levels", d:"Level should be 0–5 mm below the filler hole on each. For the transfer, pour slowly, wait about 5 minutes and recheck.", tools:["Fluid pump","Gear oil"], specs:[S("Transfer filler / drain plugs","37","27 ft·lbf"),S("Front diff filler plug","39","29 ft·lbf"),S("Rear diff filler plug","49","36 ft·lbf"),S("M/T drain / filler plug","37","27 ft·lbf",null,"mt")], man:[RM("Drivetrain","DIFFERENTIAL","DIFFERENTIAL OIL","ON-VEHICLE INSPECTION")]},
  {t:"Final-torque the suspension at ride height", d:"With the weight on the wheels, bounce each corner a few times, then torque every ride-height bolt: front lower and upper arm pivots, coilover lower, rear upper and lower arms, lateral rod, rear shock lower.", tools:["Torque wrench","Helper"], specs:[S("Front lower arm x frame","135","100 ft·lbf"),S("Front upper arm x frame","115","85 ft·lbf"),S("Coilover lower","135","100 ft·lbf"),S("Rear upper arms","80","59 ft·lbf"),S("Rear lower arms","130","96 ft·lbf"),S("Lateral control rod","130","96 ft·lbf"),S("Rear shock lower","98","72 ft·lbf")], man:[RM("General","SERVICE SPECIFICATIONS","SUSPENSION","TORQUE SPECIFICATIONS")]},
  {t:"Scan for codes", d:"Clear them, drive, and scan again. If the shift lever leaves P (A/T), or the parking brake is released (M/T), within 15 s of the first key ON after reconnecting, C1210/36 sets. That's fixed by the calibration in the next steps.", tools:["OBD2 scanner"], man:[RM("Brake","BRAKE CONTROL","VEHICLE STABILITY CONTROL SYSTEM","PRECAUTION")]},
  {t:"Wheel alignment", d:"The manual's conditions: tires checked, vehicle empty (no spare or tools aboard), corners bounced, and vehicle height checked first.", list:["4WD (GSJ15): camber 0°09′ ±30′, caster 2°49′ ±30′, SAI 12°21′ ±30′.","2WD (GSJ10): camber −0°34′, caster 3°34′.","Toe-in: 0°05′ ±0°10′.","Left–right difference 30′ or less for camber and caster.","Rack end length difference 1.0 mm or less."], tools:["Alignment shop"], specs:[S("Tie rod lock nuts","88","65 ft·lbf")], man:[RM("Suspension","SUSPENSION","FRONT WHEEL ALIGNMENT","ADJUSTMENT")]},
  {t:"VSC zero-point calibration", d:"Required after an alignment. Conditions: level ground, vehicle perfectly still, engine off, wheels straight, A/T in P or M/T in neutral, parking brake on.", list:["Clear: key ON, then connect and disconnect DLC3 Ts to CG 4+ times within 8 s.","Calibrate: key OFF, jumper Ts to CG, key ON.","Keep the truck still for 2+ s and check the VSC TRAC light blinks. If it doesn't, clear and redo."], tools:["DLC3 jumper (or Techstream)"], warn:"It runs only once per test-mode entry; clear the stored data before repeating.", man:[RM("Brake","BRAKE CONTROL","VEHICLE STABILITY CONTROL SYSTEM","CALIBRATION")]},
  {t:"Road test and retorque", d:"Recheck the cab mounts, suspension and lug nuts at 50 miles and again at 500. Log them in the notes. If your meter has a compass, drive a slow full circle to calibrate it.", tools:["Torque wrench"], specs:[S("Cab mounts","45","33 ft·lbf")]},
 ]},
];

